"""Original reproducible SVG/PNG sprites for the lounge service screens."""
from pathlib import Path
import subprocess
ROOT = Path(__file__).resolve().parents[1] / 'assets/UI/Lounge'
DEFS = '''<defs><linearGradient id="wood" x2="0" y2="1"><stop stop-color="#654832"/><stop offset=".5" stop-color="#35241b"/><stop offset="1" stop-color="#201813"/></linearGradient><linearGradient id="metal" x2=".4" y2="1"><stop stop-color="#b5aaa0"/><stop offset=".4" stop-color="#666465"/><stop offset="1" stop-color="#303133"/></linearGradient><radialGradient id="gold" cx=".3" cy=".2"><stop stop-color="#ffe7a2"/><stop offset=".6" stop-color="#bd9147"/><stop offset="1" stop-color="#6e4f21"/></radialGradient><radialGradient id="cup" cx=".3" cy=".2"><stop stop-color="#fff4d7"/><stop offset="1" stop-color="#b59870"/></radialGradient><radialGradient id="felt"><stop stop-color="#164d3b"/><stop offset="1" stop-color="#0b2e24"/></radialGradient></defs>'''
def save(name,w,h,body):
    ROOT.mkdir(parents=True,exist_ok=True)
    path=ROOT/(name+'.svg')
    path.write_text(f'<svg xmlns="http://www.w3.org/2000/svg" width="{w}" height="{h}">{DEFS}{body}</svg>')
    subprocess.run(['inkscape',str(path),'--export-filename='+str(path.with_suffix('.png'))],check=True,stdout=subprocess.DEVNULL,stderr=subprocess.DEVNULL)
def main():
    body='<rect width="1672" height="941" fill="#1b201c"/><rect x="27" y="20" width="1618" height="902" rx="35" fill="url(#wood)" stroke="#a08051" stroke-width="3"/><rect x="50" y="43" width="1572" height="856" rx="20" fill="#086044"/><rect x="60" y="53" width="1552" height="836" rx="12" fill="url(#felt)"/>'
    for x in [54,836,1618]:
        for y in [46,895]: body+=f'<circle cx="{x}" cy="{y}" r="26" fill="#090e0b"/><path d="M{x-28} {y}a28 28 0 0 1 56 0" fill="none" stroke="#88704c" stroke-width="2"/>'
    for x in [250,540,1132,1422]:
        for y in [33,908]: body+=f'<path d="M{x} {y-3}l3 3-3 3-3-3z" fill="#b99b62"/>'
    save('services_background',1672,941,body)
    save('service_anvil',320,220,'<ellipse cx="163" cy="197" rx="127" ry="17" fill="#000" opacity=".3"/><path d="M20 49h272l-30 38h-73v47l41 39v24H95v-24l41-39V87H67z" fill="url(#metal)" stroke="#252325" stroke-width="4"/><path d="M20 49l48-26h248l-24 26z" fill="#a6a5a0"/><path d="M136 88h53v46l41 39H95l41-39z" fill="#787476"/><path d="M68 28h242" stroke="#e0d8bd" stroke-width="3"/>')
