    save('service_remove',240,180,'<ellipse cx="120" cy="160" rx="110" ry="14" fill="#000" opacity=".3"/><rect x="12" y="45" width="215" height="120" rx="10" fill="url(#wood)" stroke="#a68a57" stroke-width="4"/><rect x="25" y="56" width="189" height="93" fill="#251d16"/><path d="M58 25l128 14-12 111-128-14z" fill="#e2d1a9" stroke="#a38a5c" stroke-width="3"/><circle cx="108" cy="79" r="22" fill="#405e46"/><path d="M146 66l25 28m0-25-27 25" stroke="#6a3b2b" stroke-width="6"/><path d="M12 144h215v21H12z" fill="url(#wood)" stroke="#a68a57" stroke-width="3"/>')
